#pragma once
#include "api/creative_plugin_api.h"
#include <dlfcn.h>
#include <filesystem>
#include <Python.h>
#include <string>
#include <vector>
namespace creative::plugin { class PluginManager { struct P{void* handle;creative_plugin_shutdown_fn shutdown;std::string path;bool enabled;};std::vector<P> plugins_;std::vector<std::string> python_;std::string error_; public: PluginManager(){if(!Py_IsInitialized())Py_Initialize();}~PluginManager(){clear();if(Py_IsInitialized())Py_Finalize();}bool load(const std::string&path){void*h=dlopen(path.c_str(),RTLD_NOW|RTLD_LOCAL);if(!h){error_="dlopen failed: "+path;return false;}auto init=reinterpret_cast<creative_plugin_init_fn>(dlsym(h,"creative_plugin_init"));auto shut=reinterpret_cast<creative_plugin_shutdown_fn>(dlsym(h,"creative_plugin_shutdown"));if(!init||init()!=0){dlclose(h);error_="plugin initialization failed";return false;}plugins_.push_back({h,shut,path,true});error_.clear();return true;}bool load_python(const std::string&path){FILE*f=fopen(path.c_str(),"rb");if(!f){error_="cannot open Python plugin";return false;}int r=PyRun_SimpleFile(f,path.c_str());fclose(f);if(r){error_="Python plugin failed: "+path;return false;}python_.push_back(path);error_.clear();return true;}std::size_t discover(const std::string&dir){std::size_t n=0;std::error_code ec;for(const auto&e:std::filesystem::directory_iterator(dir,ec)){if(e.path().extension()==".so"&&load(e.path().string()))++n;if(e.path().extension()==".py"&&load_python(e.path().string()))++n;}return n;}bool disable(const std::string&id){for(auto&p:plugins_)if(p.path==id){if(p.enabled&&p.shutdown)p.shutdown();p.enabled=false;return true;}return false;}void clear(){for(auto&p:plugins_){if(p.enabled&&p.shutdown)p.shutdown();dlclose(p.handle);}plugins_.clear();python_.clear();}std::size_t size()const{return plugins_.size()+python_.size();}const std::string&last_error()const{return error_;}};}
